weld::Window* GetFrameWeld(SwDocShell* pDocShell)
{
    if (!pDocShell)
        return nullptr;
    weld::Window* pRet = GetFrameWeld(pDocShell->GetMedium());
    if (!pRet)
    {
        if (SwView* pView = pDocShell->GetView())
            pRet = pView->GetFrameWeld();
    }
    return pRet;
}
